    Theorem amodelx_after_rs : AMODELX s2 mo2 /\ depot_cov d mo2.
    Proof.
      (* LPS 727298f3: the recorded proof was typed against the pre-revision munmap ledger
         (map_remove) and the flat [akernel]; it is replaced by the text proof of the same
         statement in openssl/echconfiglist_parser's As/AG_RecycleSec2.v as ported there to
         727298f3 (munmap's [maps_subtract] as a filter of [map_remove], LazyLedger.maps_subtract_rm_nz;
         [amaps_in_ledger]'s guarded first conjunct), with [akernel]'s [akernel_resx] half added
         ([akernel] is [akernel_pre /\ akernel_resx] here, As/AllocRepX.v).  The donor's unused
         SHB assertion is not taken.  No literal of the donor's proof is binary-specific. *)
      destruct AMX as [AM AK]. destruct AM as (AIL & ASV & AB). destruct AIL as (A1 & A2 & A3 & NOV & NW & NWA).
      pose proof MO as M; unfold rs_model in M; cbv beta iota zeta in M. destruct M as (NV & VM2 & VR2 & VL2 & VB2 & VK2 & VS2 & VA2 & EAG2).
      fold hh h2 in VM2, VR2, VL2, VB2, VK2, VS2, VA2.
      pose proof BND as B. bands_as (BT & _ & BP & _ & _ & BA & BS & BF & _).
      pose proof AK as AK'. destruct AK' as ((K1 & (K2a & K2c) & K3 & K4a & K4b & K4c & K5a & K5b & K5c & K6a & K6b & K7 & K8a & K8b & K8c & K9 & K10 & K11) & KRES). fold hh in K1, K2a, K2c, K3, K4a, K4b, K4c, K6a, K6b, K7, K8a, K8b, K9, K10, K11.
      assert (SHLO : sh AHI_LO = 0x2008fff7000) by (rewrite <- AHSB_eq; reflexivity). pose proof sh_ceiling_range as SCV.
      assert (WA : bv_unsigned (wz a) = a) by (unfold wz; apply unsigned_lit; clear - B; try acb; lia).
      assert (WM : bv_unsigned (wz msz) = msz) by (unfold wz; apply unsigned_lit; clear - B; try acb; lia).
      assert (E0IN : In (wz a, wz msz) (vm_maps hh)) by exact (K7 h HIN).
      (* munmap's maps_subtract, as a filter of map_remove (LazyLedger.maps_subtract_rm_nz). *)
