    Lemma keep_rs : forall x : word, in_rangesb x (vm_maps hh) = true -> ~ (a <= bv_unsigned x < a + msz) -> in_rangesb x (vm_maps h2) = true.
    Proof.
      (* rs_model's vm_maps conjunct is maps_subtract (#38: munmap's ledger
         effect, LazyLedger.v munmap_vmmapsD), so the recorded proof - which destructured the
         old map_remove conjunct and reasoned through ak_secmaps / nooverlap_in_in - no longer
         fits.  Restated as text: keeping x outside [a, a + msz) is exactly
         [zcovb_maps_subtract] (LazyLedger.v:419), on the shape of this tree's own
         [in_rangesb_subtract_keep] (As/AG_Refill3.v:46-51).  entries_nowrap of vm_maps is
         amaps_in_ledger's fifth conjunct (As/AllocRep.v:878); 0 <= a and 0 <= msz from BND. *)
      intros x Hx Hout.
      pose proof AMX as ((A & _ & _) & _). destruct A as (_ & _ & _ & _ & NWM & _).
      pose proof MO as (_ & EM & _).
      pose proof BND as B.
      change (vm_maps hh) with (vm_maps (m_vmmaps mo)) in Hx.
      change (vm_maps h2) with (vm_maps (m_vmmaps mo2)). rewrite EM.
      rewrite in_rangesb_zcovb, (zcovb_maps_subtract _ a (a + msz) _ NWM ltac:(lia) ltac:(lia)).
      rewrite <- in_rangesb_zcovb, Hx. unfold zinb.
      destruct (Z.leb_spec a (bv_unsigned x)); destruct (Z.ltb_spec (bv_unsigned x) (a + msz)); cbn; try reflexivity; lia.
    Qed.
    Lemma avmx_after_rs : avmx s s2 mo mo2.
    Proof.
      intros x Hx. split.
      - destruct (Z.lt_ge_cases (bv_unsigned x) a) as [LT|GE]; [left; apply keep_rs; [exact Hx| clear - LT; lia]|].
        destruct (Z.lt_ge_cases (bv_unsigned x) (a + msz)) as [LT2|GE2]; [| left; apply keep_rs; [exact Hx| clear - GE2; lia]].
        right. exists h. split; [exact HIN|]. split; [| exact (conj GE LT2)].
        intros Hin. change (as_sec (a_st s2)) with l1 in Hin. exact (proj2 (proj1 (L1IN h) Hin) eq_refl).
      - intros sc Hin NIn. exfalso. apply NIn. change (as_sec (a_st s2)) with l1 in Hin. exact (SUB1 sc Hin).
    Qed.
